    """
    Finds the product of non-repeated elements in a given array.
    If no non-repeated elements exist, it returns 0 or 1 based on preference; 
    here it returns 0 if the list of unique elements is empty.
    """
    # Count occurrences of each element
    counts = {}
    for num in arr:
        counts[num] = counts.get(num, 0) + 1

    # Filter elements that appear exactly once
    non_repeated = [num for num, count in counts.items() if count == 1]

    if not non_repeated:
        return 0

    # Calculate the product
    product = 1
    for num in non_repeated:
        product *= num

    return product

